export const COPY: Record<CopyLocale, Record<string, string>> = {
  hi: { ...HI, ...HI_UI },
  mr: { ...MR, ...MR_UI },
  gu: { ...GU, ...GU_UI },
};

/** Translate one string for a locale. English, and any locale without an entry, gets the string back unchanged. */
export function tr(locale: string, text: string): string {
  const dict = COPY[locale as CopyLocale];
  return (dict && dict[text]) || text;
}

/**
 * Translate every string field of a content object. Arrays and nested objects
 * are walked; numbers, booleans, and strings without an entry pass through, so
 * a "₹31,200" or an image path is never touched.
 */
export function localizeDeep<T>(locale: string, value: T): T {
  if (locale === "en") return value;
  if (typeof value === "string") return tr(locale, value) as unknown as T;
  if (Array.isArray(value)) return value.map((v) => localizeDeep(locale, v)) as unknown as T;
  if (value && typeof value === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) out[k] = localizeDeep(locale, v);
    return out as T;
  }
  return value;
}
